"""Render only completed, locked empirical results; never fill missing results."""
import json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1]
def load(p):return json.loads((ROOT/p).read_text(encoding='utf8'))
def export(fig,name):
 for ext in ['png','pdf']:fig.savefig(ROOT/'figures'/(name+'.'+ext),dpi=240,bbox_inches='tight',pad_inches=.12)
 plt.close(fig)
def main():
 result=load('results/FINAL_ANALYSIS.json');lock=load('configs/FINAL_LOCK.json');val=load('results/validation_analysis.json');dis=load('results/discovery_analysis.json');cost=load('results/PILOT_COST.json');budget=load('logs/round_budget.json')
 plt.rcParams.update({'font.family':'DejaVu Sans','font.size':12,'axes.spines.top':False,'axes.spines.right':False,'axes.linewidth':1.2,'legend.frameon':False,'pdf.fonttype':42,'ps.fonttype':42})
 methods=['keep','forward','rollback','negative','proxy','geometry','confidence','support','format_support','ensemble','head_controls_accuracy','head_new_accuracy','head_combined_accuracy']
 names={'keep':'Original Ouro','forward':'Fixed LoopCD','rollback':'Rollback (depth 3)','negative':'Negative guidance','proxy':'Question-loss proxy','geometry':'Update alignment','confidence':'Confidence selector','support':'Token support','format_support':'Two-format support','ensemble':'Two-format ensemble','head_controls_accuracy':'Confidence head','head_new_accuracy':'New-signal head','head_combined_accuracy':'Combined head'}
 fig,axes=plt.subplots(1,2,figsize=(14,7),sharey=True,layout='constrained')
 for ax,(task,r) in zip(axes,result['reports'].items()):
  ks=[k for k in methods if k in r['summary']];ys=np.arange(len(ks));v=[r['summary'][k] for k in ks];delta=np.array([x['delta_pp'] for x in v]);ci=np.array([x['ci95_pp'] for x in v]);ax.errorbar(delta,ys,xerr=np.maximum(0,np.array([delta-ci[:,0],ci[:,1]-delta])),fmt='o',color='#0F4D92',capsize=3);ax.axvline(0,color='#777777',linestyle='--');ax.set_title(task.replace('final_','').upper()+f" (n={r['n']})");ax.set_yticks(ys,[names[k] for k in ks]);ax.set_xlabel('Accuracy change vs Adaptive (pp)');ax.grid(axis='x',alpha=.15)
 axes[0].invert_yaxis();fig.suptitle('Predeclared diagnostic policies; paired 95% bootstrap intervals');export(fig,'accuracy_vs_adaptive')
 fig,axes=plt.subplots(1,2,figsize=(14,6),sharey=True,layout='constrained')
 ks=[k for k in ['forward','rollback','proxy','geometry','head_combined_accuracy','ensemble'] if k in next(iter(result['reports'].values()))['summary']]
 for ax,(task,r) in zip(axes,result['reports'].items()):
  ys=np.arange(len(ks));ax.barh(ys,[r['summary'][k]['corrections'] for k in ks],color='#8BCF8B',edgecolor='black',linewidth=.6,label='Corrections');ax.barh(ys,[-r['summary'][k]['degradations'] for k in ks],color='#B64342',edgecolor='black',linewidth=.6,label='Degradations');ax.set_yticks(ys,[names[k] for k in ks]);ax.axvline(0,color='black',linewidth=.8);ax.set_xlabel('Question count vs Adaptive');ax.set_title(task.replace('final_','').upper());ax.legend()
 axes[0].invert_yaxis();export(fig,'paired_corrections')
 fig,axes=plt.subplots(1,2,figsize=(11,4),layout='constrained')
 headnames=['head_controls_accuracy','head_new_accuracy','head_combined_accuracy'];actions=['keep','forward','rollback']
 for ax,(task,r) in zip(axes,result['reports'].items()):
  values=[[r['head_diagnostics'].get(h,{}).get(a,{}).get('auc') for a in actions] for h in headnames];vals=np.array([[v if v is not None else np.nan for v in row] for row in values]);im=ax.imshow(vals,vmin=0,vmax=1,cmap='RdBu');ax.set_xticks(range(3),[a+'\n'+str(r['head_diagnostics'][headnames[0]][a]['positive'])+'+ / '+str(r['head_diagnostics'][headnames[0]][a]['negative'])+'−' for a in actions]);ax.set_yticks(range(3),['Confidence','New signals','Combined']);ax.set_title(task.replace('final_','').upper())
  for (i,j),v in np.ndenumerate(vals):ax.text(j,i,'NA' if np.isnan(v) else f'{v:.3f}',ha='center',va='center',color='black' if np.isnan(v) or .25<v<.75 else 'white')
 fig.suptitle('Correctness-gain heads; labels show beneficial / harmful event counts',fontsize=11);fig.colorbar(im,ax=axes,label='AUC on nonzero update-value events',shrink=.85);export(fig,'head_predictability')
 fig,ax=plt.subplots(figsize=(8,4),layout='constrained');ratios=[1,cost['all_readouts_probe_seconds']/cost['baseline_seconds'],cost['two_views_seconds']/cost['baseline_seconds']];bars=ax.bar(['Adaptive LoopCD','All readouts + probes','Two views'],ratios,color=['#CFCECE','#0F4D92','#42949E'],edgecolor='black',linewidth=.7);ax.set_ylabel('Measured wall-time ratio');ax.set_ylim(0,max(ratios)*1.2)
 for b,v in zip(bars,ratios):ax.text(b.get_x()+b.get_width()/2,v+.03,f'{v:.2f}×',ha='center')
 ax.set_title('12-question pilot; four recurrent loops in every condition');export(fig,'pilot_cost')
 lines=['# Frozen update-value experiment: findings','',f"Decision: **{'Ouro success; Qwen transfer required' if result['success'] else 'No-Go for a method-paper claim from this round'}**.",'',f"Locked policy: `{result['selected_policy']}`. {lock['reason']}.",'','## Scope and evidence','', 'Frozen official Ouro-1.4B, four loops, BF16. Discovery400, supervised-training3200, validation800, and independent final SciQ1000 / PIQA1802. All new tasks are zero-shot; historical ARC25-shot and Qwen600 remain exposed historical evidence. SciQ includes official support paragraphs. PIQA excludes36 duplicate question texts before inference.','', 'The precommitted primary metric, supported by the official harness, is full-candidate character-normalized accuracy; raw accuracy is retained in FINAL_ANALYSIS.json. No final labels were used to choose signs, thresholds, features or models.','', 'Complete paired counts, validation gates, random controls and incremental head AUC intervals are in [STATISTICAL_APPENDIX.md](STATISTICAL_APPENDIX.md).','', '## Final accuracy','', '| Policy | SciQ correct /1000 | SciQ % | PIQA correct /1802 | PIQA % |','|---|---:|---:|---:|---:|']
 s=result['reports']['final_sciq']['summary'];p=result['reports']['final_piqa']['summary']
 for k in ['adaptive']+methods+['head_controls_logweight','head_new_logweight','head_combined_logweight','depth1','depth2','oracle']:
  if k in s and k in p:lines.append(f"| {names.get(k,k)} | {s[k]['correct']} | {s[k]['accuracy_percent']:.3f} | {p[k]['correct']} | {p[k]['accuracy_percent']:.3f} |")
 va=val['summary']['head_combined_accuracy']
 lines+=['',f"Validation combined accuracy head: {va['corrections']} corrections and {va['degradations']} degradations against Adaptive, net {va['net']:+d}, 95% CI [{va['ci95_pp'][0]:.3f}, {va['ci95_pp'][1]:.3f}] pp. The small number of discordant questions limits power; failure to pass this gate is insufficient evidence for a universal absence of signal."]
 lines+=['','Oracle is a label-dependent upper bound over the four permitted actions. All non-selected policy comparisons are diagnostics, even if their final point estimate is positive.','', '## Paired evidence for the locked policy','', f"Validation-selected best fixed depth: `{lock['best_fixed_depth']}`; best fixed action: `{lock['best_fixed_action']}`. These choices were frozen before final inference.",'']
 for task,r in result['reports'].items():
  for b,v in r['selected_vs_baselines'].items():lines.append(f"* {task} vs {b}: net {v['net']:+d} ({v['corrections']} corrections, {v['degradations']} degradations), {v['delta_pp']:+.3f}pp, 95%CI [{v['ci95_pp'][0]:.3f}, {v['ci95_pp'][1]:.3f}], exact McNemar p={v['mcnemar_p']:.6g}.")
 lines+=['',f"Primary Holm-adjusted p values: `{json.dumps(result['primary_adjusted_p'])}`.",'','## Answers to the nine research questions','', '1. **Signal discovered:** tested actual update-vector directions/curvature, fixed random projections, known-question-token loss residuals, token support and two-format support. These are measured signals; their existence is not evidence of predictive validity.','2. **Predicting benefit versus harm:** per-action positive/negative event counts, AUC and confidence-stratified AUC are in `FINAL_ANALYSIS.json`. The accuracy comparison above is the primary criterion; no AUC sign was reversed after observing final outcomes.','3. **Training-free usefulness:** proxy, geometry and support policies are reported individually. Validation multiple-comparison correction and the locked default determine whether a controller was accepted; discovery-only improvements are not confirmation.',f"4. **Supervision:** trained only ridge heads on true action-specific correctness deltas and, separately, gold candidate log-weight deltas. Pooled training events: {val['events']['positive']} positive, {val['events']['negative']} negative. Parameter counts: `{json.dumps(result['training_head_parameters'])}`. Only one training size was tested, so minimal sufficient supervision is not established.",'5. **Accuracy–compute trade-off:** the locked acceptance criterion requires gains over Adaptive and the two-view prompt ensemble. The ensemble and two-format selector use the same number of forward passes; it uses more passes than the single-view policies. The pilot cost plot includes probe/readout overhead. Four-loop retrospective rollback saves no recurrent compute; the full diagnostic collection is not a deployable efficiency claim.','6. **Rollback identification:** the table below distinguishes oracle recoverable cases from usable selection.','7. **Generalization:** final tasks were held out from discovery/training/validation. Qwen transfer is conditional on a successful locked Ouro controller; an unsuccessful Ouro round does not justify spending the remaining budget on transfer.','8. **Novelty:** geometry alone overlaps TAPS; gain supervision overlaps TaH2. Frozen-backbone scope differs but is insufficient novelty without new predictive information and matched accuracy gains. Readout Feedback and CoDR have different architectures/context access. See `sources/MECHANISMS.md` for primary-source mechanisms.','9. **Research decision:** '+result['decision']+'. No-Go is limited to these tested signals, labels, data and action set; it is not an impossibility theorem.','', '| Task | Rollback recovers Keep errors | Any earlier depth recovers Keep errors | Errors unreachable by four-action oracle |','|---|---:|---:|---:|']
 for task,r in result['reports'].items():
  m=r['mechanism'];lines.append(f"| {task} | {m['rollback_recovers_final_errors']} | {m['earlier_depth_any_recovers_final_errors']} | {m['unreachable_errors']} |")
 ev=result['reports']['final_sciq']['support_evidence_diagnostic'];v=ev['with_support_vs_without']
 lines+=['','## Evidence and cost controls','',f"SciQ Adaptive with support versus without support: {v['delta_pp']:+.3f}pp, paired95%CI {v['ci95_pp']}. This is an evidence-removal diagnostic, not independent verification or a causal-language-model reproduction of CoDR.",'',f"Charged additional GPU wall time: **{budget['used_seconds']/3600:.4f} hours**. Historical starting charge: {budget['historical_start_seconds']/3600:.4f}h; sum: {(budget['used_seconds']+budget['historical_start_seconds'])/3600:.4f}h. This includes startup, parity and failed workers. Head fitting used CPU ({result['training_cpu_seconds']:.2f}s total).",'', '## Correctness and limits','', 'Native final logits matched exactly. Harness likelihood errors were within the declared BF16 tolerance and predictions matched. The causal probe was checked against a prefix-only forward pass. Tests verify gold-label invariance and candidate permutation invariance. Complete exit receipts, manifest hashes, action-level paired outputs and source locks are retained.','', 'Operational recoveries are retained: discovery encountered an unavailable input-token probe; PIQA encountered a Windows progress-file sharing violation after 1492 saved records. Completed records were preserved. PIQA resumed with byte-identical frozen scoring code and a boundary replay; see REPRODUCE.md and the recovery receipts.','', 'The sample size of harmful/beneficial events can be much smaller than the question count. Sparse action-specific evidence limits power. A failed linear head does not rule out all nonlinear mechanisms, but this protocol does not respond to a negative result by indefinitely increasing model complexity.','', '![Accuracy changes](figures/accuracy_vs_adaptive.png)','', '![Paired corrections](figures/paired_corrections.png)','', '![Head AUC](figures/head_predictability.png)','', '![Pilot cost](figures/pilot_cost.png)','']
 (ROOT/'FINDINGS.md').write_text('\n'.join(lines),encoding='utf8')
 print('Wrote FINDINGS.md and four PNG/PDF figure pairs')
if __name__=='__main__':main()
